import 'package:flutter/material.dart';
import 'package:sehatak/core/models/eye/eye_models.dart';
import 'package:sehatak/core/services/eye_service.dart';
const _c=Color(0xFF9C27B0);
class EyeDoctorDetailScreen extends StatelessWidget{final String doctorId;const EyeDoctorDetailScreen({super.key,required this.doctorId});@override Widget build(BuildContext context)=>Scaffold(appBar:AppBar(title:const Text('تفاصيل طبيب العيون')),body:FutureBuilder<EyeDoctor?>(future:EyeService().getDoctor(doctorId),builder:(context,s){if(s.connectionState==ConnectionState.waiting)return const Center(child:CircularProgressIndicator());final d=s.data;if(d==null)return const Center(child:Text('الطبيب غير متوفر'));return ListView(padding:const EdgeInsets.all(16),children:[Center(child:CircleAvatar(radius:48,backgroundColor:_c.withOpacity(.1),child:const Icon(Icons.visibility,size:48,color:_c))),const SizedBox(height:14),Center(child:Text(d.name,style:const TextStyle(fontSize:21,fontWeight:FontWeight.w800))),Center(child:Text(d.specialty,style:const TextStyle(color:_c,fontWeight:FontWeight.w700))),const SizedBox(height:18),Card(child:Column(children:[ListTile(leading:const Icon(Icons.star,color:Colors.amber),title:Text('${d.rating.toStringAsFixed(1)} (${d.reviewCount} تقييم)')),ListTile(leading:const Icon(Icons.work_outline),title:Text('${d.experienceYears} سنوات خبرة')),ListTile(leading:const Icon(Icons.location_on_outlined),title:Text(d.address??'العنوان غير متوفر')),ListTile(leading:const Icon(Icons.phone_outlined),title:Text(d.phone??'الهاتف غير متوفر'))])),const SizedBox(height:18),ElevatedButton(onPressed:d.isAvailable?()=>ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('يمكنك متابعة الحجز من شاشة المواعيد'))):null,style:ElevatedButton.styleFrom(backgroundColor:_c,foregroundColor:Colors.white),child:Text(d.isAvailable?'حجز موعد':'غير متاح حالياً'))]);});}}
